import java.util.*;
public class Phase7NotificationHarness{static int p=0;static List<String> f=new ArrayList<>();enum Status{ON_TRACK,WARNING,EXCEEDED}record Plan(boolean shouldNotify,String title,String body){}static Status status(double pct){return pct>=100?Status.EXCEEDED:pct>=80?Status.WARNING:Status.ON_TRACK;}static Plan budget(double pct,long remaining){Status s=status(pct);if(s==Status.ON_TRACK)return new Plan(false,"","");if(s==Status.WARNING)return new Plan(true,"Budget warning","You've used "+pct+"% of this month's budget.");return new Plan(true,"Budget exceeded","You're over budget by "+Math.max(-remaining,0)+" minor units.");}static Plan summary(long left,long exp,long recurring){return new Plan(true,"Monthly summary","Left "+left+" · spent "+exp+" · recurring "+recurring);}static void eq(String n,Object e,Object a){if(Objects.equals(e,a))p++;else f.add(n+" expected "+e+" got "+a);}public static void main(String[]a){eq("79 no",false,budget(79.99,1).shouldNotify());eq("80 yes",true,budget(80,1).shouldNotify());eq("80 title","Budget warning",budget(80,1).title());eq("100 exceeded",Status.EXCEEDED,status(100));eq("over body","You're over budget by 500 minor units.",budget(120,-500).body());eq("summary title","Monthly summary",summary(3000,2000,500).title());System.out.println("PASSED: "+p+" assertions");if(!f.isEmpty()){f.forEach(System.out::println);System.exit(1);}System.out.println("ALL PHASE 7 NOTIFICATION CHECKS PASSED");}}
